/* ---- s2_selftest.c implementation ---- */
int s2_selftest(S2PolicyWorkspace *w,float *max_error) {
    unsigned i,j;float raw[2],error=0;
    if(!w || !max_error) return -1;
    *max_error=0;
    for(i=0;i<3;++i) {
        if(s2_policy_forward(test_obs[i],raw,w)) return -1;
        for(j=0;j<2;++j) error=fmaxf(error,fabsf(raw[j]-test_raw[i][j]));
    }
    *max_error=error;return error<=2e-5f ? 0 : -1;
}
